import os, sys, json, csv

BASE = os.path.join("storage", "shared", "agency_lab", "analyses")
CSV_DIR = os.path.join(BASE, "csv")
MANIFEST = os.path.join(BASE, "analysis_manifest_v1.json")
OUT = os.path.join(CSV_DIR, "transgen_successions_v0_1.csv")

def load_manifest(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def infer_successions(man):
    # Expected keys (robust to slight variants):
    # man["divergence_trend"] as list of {"from": g, "to": g+1, "divergence_score": x}
    # man["successions"] optionally contains c2f info; otherwise man["derived_c2f"] or similar map
    out = []
    div_map = {}
    if isinstance(man.get("divergence_trend"), list):
        for row in man["divergence_trend"]:
            try:
                g_from = int(row.get("from") or row.get("g_from") or row.get("start") or -1)
                g_to = int(row.get("to") or row.get("g_to") or row.get("end") or -1)
                div = float(row.get("divergence_score") or row.get("divergence") or row.get("div") or 0.0)
                div_map[(g_from, g_to)] = div
            except Exception:
                pass

    # Try reported/derived c2f sources
    c2f_entries = []
    if isinstance(man.get("successions"), list):
        for row in man["successions"]:
            g_from = int(row.get("from") or row.get("g_from") or row.get("start") or -1)
            g_to = int(row.get("to") or row.get("g_to") or row.get("end") or -1)
            if "ceiling_to_floor_start" in row:
                c2f_entries.append((g_from, g_to, float(row["ceiling_to_floor_start"]), "reported"))
    # Fallback: derived map like {"G6->G7": 0.0}
    for k in ("derived_c2f", "c2f_derived", "derived_ceiling_to_floor_start"):
        if isinstance(man.get(k), dict):
            for key, val in man[k].items():
                try:
                    if "->" in key:
                        a, b = key.replace("G","").split("->")
                        g_from, g_to = int(a), int(b)
                    else:
                        # try tuple-like "(6,7)"
                        s = key.strip().strip("()")
                        a, b = s.split(",")
                        g_from, g_to = int(a), int(b)
                    c2f_entries.append((g_from, g_to, float(val), "derived"))
                except Exception:
                    pass

    # Merge on (from,to)
    c2f_map = {}
    src_map = {}
    for g_from, g_to, v, src in c2f_entries:
        c2f_map[(g_from, g_to)] = v
        src_map[(g_from, g_to)] = src

    keys = set(div_map.keys()) | set(c2f_map.keys())
    rows = []
    for (g_from, g_to) in sorted(keys):
        rows.append({
            "from_generation": g_from,
            "to_generation": g_to,
            "divergence_score": div_map.get((g_from, g_to), ""),
            "ceiling_to_floor_start": c2f_map.get((g_from, g_to), ""),
            "source": src_map.get((g_from, g_to), "n/a"),
        })
    return rows

def main():
    os.makedirs(CSV_DIR, exist_ok=True)
    man = {}
    try:
        man = load_manifest(MANIFEST)
    except Exception as e:
        print("ERROR reading manifest:", e)
        return 1
    rows = infer_successions(man)
    if not rows:
        print("ERROR no successions inferred; update manifest or provide successions list.")
        return 2
    with open(OUT, "w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=["from_generation","to_generation","divergence_score","ceiling_to_floor_start","source"])
        w.writeheader()
        w.writerows(rows)
    print("WROTE", OUT, "rows=", len(rows))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
